@Test
public void testConcurrentParsing() throws IvoryException, InterruptedException {
    Thread thread = new Thread() {

        public void run() {
            Process def = null;
            try {
                def = (Process) parser.parse(this.getClass().getResourceAsStream(SAMPLE_PROCESS_XML));
            } catch (IvoryException e) {
                e.printStackTrace();
            }
        }
    };
    Thread thread1 = new Thread() {

        public void run() {
            Process def = null;
            try {
                def = (Process) parser.parse(ProcessEntityParserTest.class.getResourceAsStream(SAMPLE_PROCESS_XML));
            } catch (IvoryException e) {
                e.printStackTrace();
            }
        }
    };
    Thread thread2 = new Thread() {

        public void run() {
            Process def = null;
            try {
                def = (Process) parser.parse(this.getClass().getResourceAsStream(SAMPLE_PROCESS_XML));
            } catch (IvoryException e) {
                e.printStackTrace();
            }
        }
    };
    thread1.start();
    thread2.start();
    thread.start();
    Thread.sleep(5000);
}

